import java.util.Scanner;

public class Main {
    static final int MAXN = 600;
    static long mod;
    static BigInt[][] comb = new BigInt[MAXN + 1][MAXN + 1];
    static BigInt[] a = new BigInt[MAXN + 1];
    static BigInt[] c = new BigInt[MAXN + 1];
    static BigInt[][][] dp = new BigInt[MAXN + 1][MAXN + 1][2];
    static BigInt[][][] dpc = new BigInt[MAXN + 1][MAXN + 1][2];

    static class BigInt {
        long v;

        BigInt() {
            v = 0;
        }

        BigInt(long _v) {
            v = _v % mod;
            if (v < 0) v += mod;
        }

        BigInt add(BigInt b) {
            return new BigInt((v + b.v) % mod);
        }

        BigInt subtract(BigInt b) {
            return new BigInt((v - b.v + mod) % mod);
        }

        BigInt multiply(BigInt b) {
            return new BigInt((v * b.v) % mod);
        }

        BigInt pow(long e) {
            BigInt res = new BigInt(1);
            BigInt base = new BigInt(v);
            while (e > 0) {
                if ((e & 1) == 1) res = res.multiply(base);
                base = base.multiply(base);
                e >>= 1;
            }
            return res;
        }

        BigInt inv() {
            return this.pow(mod - 2);
        }
    }

    static long sumRange(long l, long r) {
        if (l > r) return 0;
        return (l + r) * (r - l + 1) / 2;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        mod = sc.nextLong();

        for (int i = 0; i <= MAXN; i++) {
            for (int j = 0; j <= MAXN; j++) {
                comb[i][j] = new BigInt(0);
            }
        }

        for (int i = 0; i <= MAXN; i++) {
            comb[i][0] = new BigInt(1);
            comb[i][i] = new BigInt(1);
        }

        for (int i = 1; i <= MAXN; i++) {
            for (int j = 1; j < i; j++) {
                comb[i][j] = comb[i - 1][j - 1].add(comb[i - 1][j]);
            }
        }

        a[0] = new BigInt(0);
        c[0] = new BigInt(1);
        a[1] = new BigInt(0);
        c[1] = new BigInt(2);

        for (int i = 2; i <= m; i++) {
            BigInt tmp = new BigInt(0);
            BigInt tmpc = new BigInt(0);
            for (int l = 0; l <= i; l++) {
                int r = i - 1 - l;
                BigInt sumRangeVal = new BigInt(sumRange(1, l)).add(new BigInt(sumRange(1, r)));
                tmp = tmp.add(c[l].multiply(c[r]).multiply(sumRangeVal).multiply(comb[i - 1][l]))
                        .add((a[l].multiply(c[r]).add(a[r].multiply(c[l]))).multiply(comb[i - 1][l]).multiply(new BigInt(i + 1)));
                tmpc = tmpc.add(c[l].multiply(c[r]).multiply(new BigInt(i + 1)).multiply(comb[i - 1][l]));
            }
            a[i] = tmp;
            c[i] = tmpc;
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                for (int k = 0; k < 2; k++) {
                    dpc[i][j][k] = new BigInt(0);
                }
            }
        }
        dpc[0][0][0] = new BigInt(1);

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                if (j > i) continue;
                dpc[i][j][0] = dpc[i - 1][j][0].add(dpc[i - 1][j][1]);
                for (int k = 1; k <= j; k++) {
                    dpc[i][j][1] = dpc[i][j][1].add(c[k].multiply(comb[j][k]).multiply(dpc[i - k][j - k][0]));
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                if (j > i) continue;
                dp[i][j][0] = dp[i - 1][j][0].add(dp[i - 1][j][1]);
                for (int k = 1; k <= j; k++) {
                    BigInt term1 = a[k].multiply(comb[j][k]).multiply(dpc[i - k][j - k][0]);
                    BigInt term2 = dp[i - k][j - k][0].multiply(c[k]).multiply(comb[j][k]);
                    dp[i][j][1] = dp[i][j][1].add(term1).add(term2);
                }
            }
        }

        BigInt result = dp[n][m][0].add(dp[n][m][1]);
        System.out.println(result.v);
        sc.close();
    }
}
